import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, color, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, PointLight } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // 1. Create Card Geometry (Nova Atelier specification size)
  const width = 3.2;
  const height = 4.0;
  const geometry = new PlaneGeometry(width, height, 64, 64);

  // 2. Build Engineered Gradient Material using TSL
  const material = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    flatShading: false
  });

  const uvNode = uv();

  // Base gradient: Near-black surface (#0b0b10) to Ink (#16161d)
  const colorA = color('#0b0b10');
  const colorB = color('#16161d');
  const grad = mix(colorA, colorB, uvNode.y);

  // Precision engineered Accent Signal Red (#ff2a38) pinstripe along the left border
  const accentStrip = smoothstep(0.02, 0.025, uvNode.x).mul(smoothstep(0.035, 0.03, uvNode.x));

  // Blend gradient and accent line
  const finalColor = mix(grad, color('#ff2a38'), accentStrip);
  material.colorNode = finalColor;

  // 3. Create Mesh
  const cardMesh = new Mesh(geometry, material);
  group.add(cardMesh);

  // Load brushed metal map if available and hook into material roughness/metalness
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.anisotropy = 8;
      material.roughnessMap = texture;
      material.metalnessMap = texture;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load asset texture:', err);
    });
  }

  // 4. Local Product Lighting: Machined rim lighting local to the card
  const localRimLight = new PointLight('#e8ecf2', 1.2, 8);
  localRimLight.position.set(-2, 2, 1.5);
  group.add(localRimLight);

  const localAccentLight = new PointLight('#ff2a38', 0.8, 6);
  localAccentLight.position.set(2, -2, 1);
  group.add(localAccentLight);

  // 5. Render Texts dynamically if provided
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.z = 0.05; // Slightly offset to prevent z-fighting
  group.add(textGroup);

  let currentY = 1.4;
  items.forEach((item) => {
    const isHeader = item.role === 'heading' || item.role === 'title';
    const fontSize = isHeader ? 0.34 : 0.13;
    const fontColor = isHeader ? '#e8ecf2' : '#ff2a38';

    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize,
      color: fontColor,
      align: 'center'
    });

    textMesh.position.set(0, currentY, 0);
    textGroup.add(textMesh);
    currentY -= (fontSize + 0.25);
  });

  // 6. Non-interactive Entrance Motion (Weighted Settle)
  group.position.y += 0.4;
  group.scale.set(0.95, 0.95, 0.95);

  const introTimeline = gsap.timeline();
  introTimeline.to(group.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out'
  });
  introTimeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  timelines.push(introTimeline);

  // 7. Cleanup Hook
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    geometry.dispose();
    material.dispose();
  };

  return group;
}
